module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] buffer [0:3];
integer top;

initial begin
    top = -1;
    EMPTY = 1;
    FULL = 0;
end

always @(posedge Clk or posedge Rst) begin
    if (Rst) begin
        top = -1;
        EMPTY <= 1;
        FULL <= 0;
        dataOut <= 4'b0000;
    end else begin
        if (EN) begin
            if (!FULL && !RW) begin
                top = top + 1;
                buffer[top] <= dataIn;
                if (top == 3)
                    FULL <= 1;
                EMPTY <= 0;
            end else if (!EMPTY && RW) begin
                dataOut <= buffer[top];
                top = top - 1;
                if (top == -1)
                    EMPTY <= 1;
                FULL <= 0;
            end
        end
    end
end

endmodule
